"""
convert_any_to_hdf5.py
~~~~~~~~~~~~~~~~~~~~~~

Command‑line utility that converts a collection of simulation results into a single,
portable HDF5 “master bundle”.  Supported protocols are:

* **kth** – a tab‑separated CSV summary (generated by the KTH protocol) and a
  hierarchy of simulation sub‑directories referenced by that CSV.
* **uva** – a directory where each immediate sub‑folder contains an independent
  UVA simulation.

For each identified protocol a master‑bundle is instantiated and written as a
top‑level group in the output HDF5 file.  Optionally the original raw input
directory is zipped and stored as an external link under the ``raw_bundle`` group.

Typical invocation
------------------

    python convert_any_to_hdf5.py -i /path/to/input -o /path/to/master.h5 \\
        --protocol uva [--no-raw-bundle] [--log-level INFO] \\
        [--protocol-version 1.0.0] [--protocol-info-path /path/to/protocol_info.pdf] \\
        [--parameters scale_num_neurons scale_syn_strength] \\
        [--meta-author "John Doe" --meta-project "NeuroSim" ...]

    python convert_any_to_hdf5.py -i /path/to/input/run_list.csv -o /path/to/master.h5 \\
        --protocol kth [--no-raw-bundle] [--log-level INFO] \\
        [--protocol-version 1.0.0] [--protocol-info-path /path/to/protocol_info.pdf] \\
        [--parameters scale_num_neurons scale_syn_strength] \\
        [--meta-author "John Doe" --meta-project "NeuroSim" ...]

Arguments
---------

* ``-i / --input``
  Path to the input CSV (KTH) or root directory (UVA).

* ``-o / --output``
  Destination HDF5 file (or directory containing it).  The parent directory is
  created automatically if it does not exist.

* ``--protocol``
  Choose which protocol parser to use – either ``kth`` or ``uva``.

* ``--no-raw-bundle``
  When given, the original raw input directory is **not** zipped and stored in the
  ``raw_bundle`` group.  By default the raw data are embedded as a zipped archive.

* ``--protocol-version``
  The protocol version string to be recorded in the bundle (default: ``1.0.0``).

* ``--protocol-info-path``
  Path to a PDF file containing the protocol description.  The placeholder
  ``{{input}}`` can be used to refer to the input directory (default:
  ``{{input}}/protocol_info.pdf``).

* ``--log-level``
  Logging verbosity (default ``INFO``).  Accepted values are ``DEBUG``, ``INFO``,
  ``WARNING``, ``ERROR`` and ``CRITICAL``.

* ``--parameters`` *PARAM1 PARAM2 …*
  Override the built‑in list of dynamic parameters for the selected protocol.
  Supply one or more space‑separated identifiers, e.g.
  ``--parameters scale_num_neurons scale_syn_strength``.

* ``--meta‑author``
  Value for the meta‑data field ``author``.

* ``--meta‑creation-date``
  Value for the meta‑data field ``creation_date`` (ISO‑8601 string format).

* ``--meta‑affiliation``
  Value for the meta‑data field ``affiliation``.

* ``--meta‑project``
  Value for the meta‑data field ``project``.

* ``--meta‑simulation-name``
  Value for the meta‑data field ``simulation_name``.

* ``--meta‑run-id``
  Value for the meta‑data field ``run_id``.

* ``--meta‑software``
  Value for the meta‑data field ``software``.

* ``--meta‑software-version``
  Value for the meta‑data field ``software_version``.

* ``--meta‑license``
  Value for the meta‑data field ``license``.

* ``--meta‑contact-email``
  Value for the meta‑data field ``contact_email``.

* ``--meta‑comment``
  Value for the meta‑data field ``comment``.

All ``--meta‑*`` options are optional; any that are supplied are stored in the
bundle’s ``metadata`` attribute.  The ``--parameters`` option is also optional
and, if omitted, the protocol‑specific default parameter set is used.

The script creates the output directory if needed, writes a ``format_version``
attribute to the HDF5 root, and logs progress and errors to **STDERR**.
"""
from __future__ import annotations

import argparse
import logging
import sys
from pathlib import Path

from converters.factory.protocol_registry import PROTOCOL_BUILDERS
from converters.utils.common import configure_logging
from converters.utils.zip_helper import zip_directory

logger = configure_logging(
    __name__,
    log_file_name=Path(__file__).with_suffix(".log").name,
    level=logging.INFO,
)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Convert a collection of simulation results into a master HDF5 bundle (new schema)."
    )
    parser.add_argument("-i", "--input", required=True, help="Input directory (UVA) or CSV (KTH).")
    parser.add_argument("-o", "--output", required=True, help="Path to the master *.h5* file that will be created.")
    parser.add_argument(
        "--protocol",
        choices=["kth", "uva"],
        required=True,
        help="Which protocol to interpret the input as.",
    )
    parser.add_argument("--no-raw-bundle",
                        action="store_true",
                        help="Do NOT embed the zipped original directory.")
    parser.add_argument("--protocol-version",
                        default="1.0.0",
                        help="The protocol version which shall be incorporated.")
    parser.add_argument("--protocol-info-path",
                        default="{{input}}/protocol_info.pdf",
                        help="The PDF file containing the protocol information shall be incorporated. If it is not provided, the file is expected to be located in the input folder.")
    parser.add_argument(
        "--log-level",
        default="INFO",
        choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"],
        help="Logging verbosity.",
    )
    parser.add_argument(
        "--parameters",
        nargs="+",  # one or more values, space‑separated
        default=None,
        help=(
            "Override the built‑in list of dynamic parameters for the selected "
            "protocol.  Give a space‑separated list, e.g. "
            "--parameters scale_num_neurons scale_syn_strength"
        ),
    )
    parser.add_argument(
        "--meta-author",
        help="Value for meta‑data field ‘author’.",
    )
    parser.add_argument(
        "--meta-creation-date",
        help="Value for meta‑data field ‘creation_date’ (ISO‑8601 string format).",
    )
    parser.add_argument(
        "--meta-affiliation",
        help="Value for meta‑data field ‘affiliation’.",
    )
    parser.add_argument(
        "--meta-project",
        help="Value for meta‑data field ‘project’.",
    )
    parser.add_argument(
        "--meta-simulation-name",
        help="Value for meta‑data field ‘simulation_name’.",
    )
    parser.add_argument(
        "--meta-run-id",
        help="Value for meta‑data field ‘run_id’.",
    )
    parser.add_argument(
        "--meta-software",
        help="Value for meta‑data field ‘software’.",
    )
    parser.add_argument(
        "--meta-software-version",
        help="Value for meta‑data field ‘software_version’.",
    )
    parser.add_argument(
        "--meta-license",
        help="Value for meta‑data field ‘license’.",
    )
    parser.add_argument(
        "--meta-contact-email",
        help="Value for meta‑data field ‘contact_email’.",
    )
    parser.add_argument(
        "--meta-comment",
        help="Value for meta‑data field ‘comment’.",
    )
    args = parser.parse_args()

    logging.basicConfig(
        level=getattr(logging, args.log_level),
        format="%(asctime)s [%(levelname)s] %(message)s",
        handlers=[logging.StreamHandler(sys.stderr)],
    )

    input_path = Path(args.input).expanduser().resolve()
    input_dir = input_path if input_path.is_dir() else input_path.parent
    out_path = Path(args.output).expanduser().resolve()
    out_dir = out_path if out_path.is_dir() else out_path.parent
    raw_zip = out_dir / f"raw_data.zip"
    proto_path = (
        args.protocol_info_path.replace("{{input}}", str(input_dir), 1)
        if args.protocol_info_path.startswith("{{input}}")
        else args.protocol_info_path
    )
    protocol_info_path = Path(proto_path).expanduser().resolve()
    if not args.no_raw_bundle:
        zip_directory(src_root=input_dir, dst_zip=raw_zip)
    try:
        builder = PROTOCOL_BUILDERS[args.protocol]  # KeyError → unknown protocol (should never happen)
    except KeyError:
        logger.error("Unsupported protocol %s", args.protocol)
        sys.exit(1)
    extra_kwargs: dict = {}
    if args.parameters is not None:
        extra_kwargs["parameters"] = args.parameters

    metadata_kwargs: dict[str, str] = {}
    for arg_name, std_key in {
        "meta_author": "author",
        "meta_creation_date": "creation_date",
        "meta_affiliation": "affiliation",
        "meta_project": "project",
        "meta_simulation_name": "simulation_name",
        "meta_run_id": "run_id",
        "meta_software": "software",
        "meta_software_version": "software_version",
        "meta_license": "license",
        "meta_contact_email": "contact_email",
        "meta_comment": "comment",
    }.items():
        value = getattr(args, arg_name)
        if value is not None:
            metadata_kwargs[std_key] = value

    # Pass the metadata dict as an extra keyword argument
    if metadata_kwargs:
        extra_kwargs["metadata"] = metadata_kwargs

    master = builder(
        input_path=input_path,
        embed_raw=not args.no_raw_bundle,
        embed_raw_path=raw_zip,
        output_dir=out_dir,
        protocol_version=args.protocol_version,
        protocol_info_path=protocol_info_path,
        **extra_kwargs,
    )

    # Write the file
    master.to_hdf5(out_path)
    raw_zip.unlink(missing_ok=True)  # Remove the temporary zip file if it was created
    logger.info("Finished – master file written to %s", out_path)


if __name__ == "__main__":
    main()
